data = sys.stdin.read().split()
r, c, k = int(data[0]), int(data[1]), int(data[2])
rows = []
pos = 3
for _ in range(r):
    m = 0
    for j in range(c):
        if data[pos + j] == '1':
            m |= 1 << j
    rows.append(m)
    pos += c
full = (1 << c) - 1
reach = {0}
for _ in range(k):
    reach = {s ^ (1 << j) for s in reach for j in range(c)}
best = 0
for s in reach:
    best = max(best, sum(1 for m in rows if m ^ s == full))
print(best)

